// JarvisBuild.js — the Build-mode IDE.

// When the admin flips the composer to Build, the chat page is replaced by this
// VS Code-style workspace: a file tree of the real workspace on the left, an
// editor in the middle, the agent conversation docked on the right, and a
// terminal across the bottom. It runs the unclamped agent (write + execute) on
// the admin's private server, so the files it shows are real and the edits it
// makes are real.

// It is deliberately self-contained: it takes the live agent state + handlers as
// an `agent` prop and renders the panels around them, rather than entangling
// with the chat page's markup. The one shared dependency is MdLite for answers.

import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import MdLite from "../../../utils/MdLite";
import { fetchBuildFile, fetchBuildTree } from "./jarvisClient";
import "./JarvisBuild.css";

const WELCOME_TAB = "__welcome__";

// Panel geometry (px). Clamped on drag so no panel can be dragged away.
const EXPLORER_MIN = 170;
const EXPLORER_MAX = 460;
const CHAT_MIN = 280;
const CHAT_MAX = 640;
const TERM_MIN = 34; // header height — drag all the way down to "collapse"
const STICK_SLOP = 72; // px from the bottom that still counts as "at bottom"

// ---- small helpers ---------------------------------------------------------
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));

const isAtBottom = (el) =>
  !el || el.scrollHeight - el.scrollTop - el.clientHeight < STICK_SLOP;

const baseName = (p = "") => p.split("/").pop();

const formatMs = (ms) =>
  ms == null
    ? ""
    : ms < 1000
    ? `${Math.round(ms)}ms`
    : `${(ms / 1000).toFixed(1)}s`;

const isMarkdown = (path) => /\.m(d|arkdown)$/i.test(path || "");

// A small colored glyph per file type — enough to read a tree at a glance,
// like an editor's file icons, without pulling in an icon font.
function fileMeta(name = "") {
  const ext = (name.split(".").pop() || "").toLowerCase();
  const map = {
    js: ["JS", "#e5c07b"],
    jsx: ["JS", "#e5c07b"],
    ts: ["TS", "#4fc3f7"],
    tsx: ["TS", "#4fc3f7"],
    py: ["PY", "#5aa9e6"],
    html: ["<>", "#e06c5f"],
    htm: ["<>", "#e06c5f"],
    css: ["#", "#56b6c2"],
    scss: ["#", "#c678dd"],
    json: ["{}", "#98c379"],
    md: ["M", "#9aa0a6"],
    markdown: ["M", "#9aa0a6"],
    sh: ["$", "#98c379"],
    bash: ["$", "#98c379"],
    txt: ["≡", "#9aa0a6"],
    yml: ["Y", "#e5c07b"],
    yaml: ["Y", "#e5c07b"],
    toml: ["T", "#e5c07b"],
    sql: ["DB", "#e5c07b"],
  };
  return map[ext] || ["•", "#7f8794"];
}

// ---- file tree -------------------------------------------------------------
// Filter keeps a folder when it matches, or when any descendant matches, so the
// path to a hit stays readable instead of collapsing to bare filenames.
function filterTree(nodes, query) {
  if (!query) return nodes;
  const needle = query.toLowerCase();
  const walk = (list) =>
    (list || []).reduce((acc, node) => {
      if (node.type === "dir") {
        const kids = walk(node.children);
        const self = node.name.toLowerCase().includes(needle);
        if (kids.length || self) acc.push({ ...node, children: kids });
      } else if (node.name.toLowerCase().includes(needle)) {
        acc.push(node);
      }
      return acc;
    }, []);
  return walk(nodes);
}

function collectDirPaths(nodes, out = []) {
  (nodes || []).forEach((node) => {
    if (node.type === "dir") {
      out.push(node.path);
      collectDirPaths(node.children, out);
    }
  });
  return out;
}

function countFiles(nodes) {
  return (nodes || []).reduce(
    (n, node) => n + (node.type === "dir" ? countFiles(node.children) : 1),
    0
  );
}

function Highlight({ text, query }) {
  if (!query) return <>{text}</>;
  const i = text.toLowerCase().indexOf(query.toLowerCase());
  if (i < 0) return <>{text}</>;
  return (
    <>
      {text.slice(0, i)}
      <mark className="jvb-hl">{text.slice(i, i + query.length)}</mark>
      {text.slice(i + query.length)}
    </>
  );
}

function TreeNode({
  node,
  depth,
  activePath,
  recentPath,
  expanded,
  query,
  onToggle,
  onOpen,
}) {
  const pad = { paddingLeft: `${8 + depth * 12}px` };

  if (node.type === "dir") {
    const isOpen = expanded.has(node.path);
    return (
      <div className="jvb-tree-folder">
        <button
          type="button"
          className="jvb-tree-row jvb-tree-dir"
          style={pad}
          aria-expanded={isOpen}
          onClick={() => onToggle(node.path)}
        >
          <span className={`jvb-tree-caret ${isOpen ? "open" : ""}`}>›</span>
          <span className="jvb-tree-name">
            <Highlight text={node.name} query={query} />
          </span>
        </button>
        {isOpen &&
          node.children?.map((child) => (
            <TreeNode
              key={child.path}
              node={child}
              depth={depth + 1}
              activePath={activePath}
              recentPath={recentPath}
              expanded={expanded}
              query={query}
              onToggle={onToggle}
              onOpen={onOpen}
            />
          ))}
      </div>
    );
  }

  const [glyph, color] = fileMeta(node.name);
  return (
    <button
      type="button"
      className={`jvb-tree-row jvb-tree-file ${
        activePath === node.path ? "active" : ""
      } ${recentPath === node.path ? "just-written" : ""}`}
      style={pad}
      onClick={() => onOpen(node.path)}
      title={node.path}
    >
      <span className="jvb-tree-ic" style={{ color }} aria-hidden="true">
        {glyph}
      </span>
      <span className="jvb-tree-name">
        <Highlight text={node.name} query={query} />
      </span>
      {recentPath === node.path && (
        <span className="jvb-tree-tag" title="Just written by Jarvis">
          new
        </span>
      )}
    </button>
  );
}

// ---- call rendering (mirrors the Explore trace, so the terminal matches) ----
const CALL_TOKEN = /("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\b(?:True|False|None)\b|\b\d+(?:\.\d+)?\b|[A-Za-z_]\w*(?=\s*=))/g;

function tokenClass(token) {
  if (token[0] === '"' || token[0] === "'") return "jvt-str";
  if (/^(True|False|None)$/.test(token)) return "jvt-kw";
  if (/^\d/.test(token)) return "jvt-num";
  return "jvt-arg";
}

// Collapse any long quoted value so a write_file(content="<800 lines>") doesn't
// flood the terminal — the file itself shows in the editor.
function tidyCall(call) {
  if (!call) return call;
  return call.replace(/(["'])((?:\\.|(?!\1)[^\\])*)\1/g, (m, q, body) =>
    body.length > 44 ? `${q}${body.slice(0, 44)}…${q}` : m
  );
}

function CallCode({ text }) {
  const match = /^([A-Za-z_]\w*)\(([\s\S]*)\)$/.exec(tidyCall(text) || "");
  if (!match) return <>{text}</>;
  const [, name, args] = match;
  return (
    <>
      <span className="jvt-fn">{name}</span>
      <span className="jvt-punc">(</span>
      {args.split(CALL_TOKEN).map((part, i) =>
        i % 2 === 1 ? (
          <span className={tokenClass(part)} key={i}>
            {part}
          </span>
        ) : (
          <span className="jvt-punc" key={i}>
            {part}
          </span>
        )
      )}
      <span className="jvt-punc">)</span>
    </>
  );
}

