// ---- persisted reasoning block — the model's thinking, kept after the answer
// so a recruiter can see *how* it got there, not just the result.
function Reasoning({ text, defaultOpen = true, live = false }) {
  const [open, setOpen] = useState(defaultOpen);
  if (!text) return null;
  return (
    <div className={`jvb-reason ${live ? "live" : ""}`}>
      <button
        type="button"
        className="jvb-reason-head"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        <span className={`jvb-reason-caret ${open ? "open" : ""}`}>›</span>
        <span className="jvb-reason-dot" aria-hidden="true" />
        thinking
        {!open && <span className="jvb-reason-peek">{text.slice(0, 60)}…</span>}
      </button>
      {open && <div className="jvb-reason-body">{text}</div>}
    </div>
  );
}

// ---- one turn's execution trace, rendered terminal-style (matches Explore) --
function TerminalTurn({ lines, meta }) {
  const hasTool = (lines || []).some((l) => l.kind === "tool");
  if (!lines || (!lines.length && !meta)) return null;
  return (
    <div className="jvb-tt">
      {lines.map((line, i) => {
        if (line.kind === "tool") {
          const running = line.state === "running";
          return (
            <div className={`jvb-tt-step ${running ? "running" : ""}`} key={i}>
              <span className={`jvb-tt-num ${running ? "jvb-tt-num-run" : ""}`}>
                {line.step}
              </span>
              <code className="jvb-tt-call">
                <CallCode text={line.call || `${line.name || line.verb}(…)`} />
              </code>
              {line.ms != null && (
                <span className="jvb-tt-ms">{formatMs(line.ms)}</span>
              )}
              <span
                className={`jvb-tt-state ${
                  running ? "run" : line.ok ? "ok" : "err"
                }`}
              >
                {running ? "⋯" : line.ok ? "✓" : "✗"}
              </span>
              {line.summary && (
                <div className="jvb-tt-summary">{line.summary}</div>
              )}
            </div>
          );
        }
        return (
          <div className={`jvb-tt-line jvb-tt-${line.kind}`} key={i}>
            {line.text}
          </div>
        );
      })}
      {meta && (
        <div className="jvb-tt-meta">
          {hasTool ? meta : `${meta} · answered directly`}
        </div>
      )}
    </div>
  );
}

// Pull the path out of a write/edit/create tool call, so the IDE can reveal the
// file the agent just touched.
function writtenPathFromTurn(turn) {
  let found = null;
  for (const line of turn.lines || []) {
    if (line.kind !== "tool" || !line.call) continue;
    if (
      !/^(write_file|edit_file|create_file|apply_patch|str_replace|append_file)\b/.test(
        line.call
      )
    ) {
      continue;
    }
    const m = line.call.match(
      /(?:path|file_path|filename)\s*=\s*["']([^"']+)["']/
    );
    if (m) found = m[1];
  }
  return found;
}

const JarvisBuild = ({
  agent,
  refreshKey,
  sid = null,
  sessionState = "ready",
  sessionMessage = "",
  quota = null,
  onRetrySession,
  onExit,
  onWatchDemo,
}) => {
  const {
    turns = [],
    busy,
    streaming,
    lines = [],
    thinking,
    meta,
    input,
    setInput,
    submit,
    stop,
    provider,
  } = agent;

  const [tree, setTree] = useState([]);
  const [rootName, setRootName] = useState("workspace");
  const [expanded, setExpanded] = useState(() => new Set());
  // A welcome/guide tab is open by default so a first-time visitor immediately
  // understands what Jarvis is and how to drive it.
  const [openTabs, setOpenTabs] = useState([
    { path: WELCOME_TAB, welcome: true },
  ]);
  const [activePath, setActivePath] = useState(WELCOME_TAB);
  const [treeError, setTreeError] = useState(false);
  const [treeLoading, setTreeLoading] = useState(true);

  // layout
  const [termHeight, setTermHeight] = useState(200);
  const [explorerW, setExplorerW] = useState(244);
  const [chatW, setChatW] = useState(360);
  const [explorerOpen, setExplorerOpen] = useState(true);
  const [chatOpen, setChatOpen] = useState(true);
  const [termOpen, setTermOpen] = useState(true);
  const [pane, setPane] = useState("agent"); // narrow screens only

  // editor + explorer affordances
  const [query, setQuery] = useState("");
  const [wrap, setWrap] = useState(false);
  const [copied, setCopied] = useState(false);
  const [recentPath, setRecentPath] = useState(null);
  const [termPinned, setTermPinned] = useState(true);
  const [chatPinned, setChatPinned] = useState(true);

  const chatRef = useRef(null);
  const termRef = useRef(null);
  const inputRef = useRef(null);
  const filterRef = useRef(null);
  const tabStripRef = useRef(null);

  // ---- hide the site's floating assistant widgets while the IDE is open ----
  // They're kept (renamed) on the Explore page, but over the IDE they just
  // overlap. Scoped by a body class so unmounting restores them.
  useEffect(() => {
    document.body.classList.add("jvb-ide-open");
    return () => document.body.classList.remove("jvb-ide-open");
  }, []);

  // Focus the composer on mount — the first thing you do here is ask for something.
  useEffect(() => {
    const t = setTimeout(() => inputRef.current?.focus(), 120);
    return () => clearTimeout(t);
  }, []);

  // ---- load the workspace tree on mount + after each finished turn ----
  const loadTree = useCallback(async () => {
    const data = await fetchBuildTree(sid);
    setTreeLoading(false);
    if (!data || !data.ok) {
      setTreeError(true);
      return;
    }
    setTreeError(false);
    setRootName(data.root || "workspace");
    setTree(data.tree || []);
  }, [sid]);

  useEffect(() => {
    // Wait for the session so we don't briefly show the function's own files
    // while the sandbox is still spinning up.
    if (sessionState !== "ready") return;
    loadTree();
  }, [loadTree, refreshKey, sessionState]);

  const reloadFile = useCallback(
    async (path) => {
      if (!path || path === WELCOME_TAB) return;
      const data = await fetchBuildFile(path, sid);
      if (!data || !data.ok) return;
      setOpenTabs((prev) =>
        prev.map((t) =>
          t.path === path ? { ...t, content: data.content, loading: false } : t
        )
      );
    },
    [sid]
  );

  const openFile = useCallback(
    async (path) => {
      setActivePath(path);
      setPane("editor");
      setOpenTabs((prev) =>
        prev.some((t) => t.path === path)
          ? prev
          : [...prev, { path, content: "", loading: true }]
      );
      const data = await fetchBuildFile(path, sid);
      setOpenTabs((prev) =>
        prev.map((t) =>
          t.path === path
            ? {
                ...t,
                loading: false,
                content:
                  data && data.ok ? data.content : "// could not read file",
              }
            : t
        )
      );
    },
    [sid]
  );

  // ---- after a turn: refresh open files, and reveal what the agent wrote ----
  useEffect(() => {
    if (busy) return;
    openTabs.forEach((tab) => !tab.welcome && reloadFile(tab.path));

    // Find the file the most recent turn wrote, expand to it, and open it.
    const lastAsst = [...turns].reverse().find((t) => t.role === "assistant");
    const path = lastAsst && writtenPathFromTurn(lastAsst);
    if (path) {
      const parts = path.split("/").slice(0, -1);
      if (parts.length) {
        setExpanded((prev) => {
          const next = new Set(prev);
          let acc = "";
          for (const p of parts) {
            acc = acc ? `${acc}/${p}` : p;
            next.add(acc);
          }
          return next;
        });
      }
      openFile(path);
      setRecentPath(path);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [refreshKey]);

  // Let the "new" flag fade instead of sticking around forever.
  useEffect(() => {
    if (!recentPath) return undefined;
    const t = setTimeout(() => setRecentPath(null), 6000);
    return () => clearTimeout(t);
  }, [recentPath]);

  const closeTab = useCallback(
    (path, e) => {
      if (e) e.stopPropagation();
      setOpenTabs((prev) => {
        const next = prev.filter((t) => t.path !== path);
        if (activePath === path) {
          setActivePath(next.length ? next[next.length - 1].path : null);
        }
        return next;
      });
    },
    [activePath]
  );

  const toggleFolder = useCallback((path) => {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  }, []);

  // ---- draggable panels, like VS Code's splitters ----
  const startDrag = useCallback(
    (axis, onDelta, cursor) => (e) => {
      e.preventDefault();
      const start = axis === "y" ? e.clientY : e.clientX;
      const onMove = (ev) =>
        onDelta((axis === "y" ? ev.clientY : ev.clientX) - start);
      const onUp = () => {
        document.removeEventListener("mousemove", onMove);
        document.removeEventListener("mouseup", onUp);
        document.body.style.cursor = "";
        document.body.style.userSelect = "";
        document.body.classList.remove("jvb-dragging");
      };
      document.body.style.cursor = cursor;
      document.body.style.userSelect = "none";
      document.body.classList.add("jvb-dragging");
      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onUp);
    },
    []
  );

  const startTermResize = useMemo(() => {
    let startH = termHeight;
    return (e) => {
      startH = termHeight;
      startDrag(
        "y",
        (d) => {
          const next = clamp(startH - d, TERM_MIN, window.innerHeight * 0.75);
          setTermOpen(next > TERM_MIN + 8);
          setTermHeight(next);
        },
        "row-resize"
      )(e);
    };
  }, [termHeight, startDrag]);

  const startExplorerResize = useMemo(() => {
    let startW = explorerW;
    return (e) => {
      startW = explorerW;
      startDrag(
        "x",
        (d) => setExplorerW(clamp(startW + d, EXPLORER_MIN, EXPLORER_MAX)),
        "col-resize"
      )(e);
    };
  }, [explorerW, startDrag]);

  const startChatResize = useMemo(() => {
    let startW = chatW;
    return (e) => {
      startW = chatW;
      startDrag(
        "x",
        (d) => setChatW(clamp(startW - d, CHAT_MIN, CHAT_MAX)),
        "col-resize"
      )(e);
    };
  }, [chatW, startDrag]);

  // ---- keep chat + terminal pinned to the bottom, but only if already there --
  useEffect(() => {
    if (chatPinned && chatRef.current) {
      chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }
    if (termPinned && termRef.current) {
      termRef.current.scrollTop = termRef.current.scrollHeight;
    }
  }, [turns, streaming, lines, thinking, busy, chatPinned, termPinned]);

  // ---- keyboard shortcuts, VS Code-ish ----
  useEffect(() => {
    const onKey = (e) => {
      const mod = e.metaKey || e.ctrlKey;
      if (!mod) return;
      const k = e.key.toLowerCase();
      if (k === "b") {
        e.preventDefault();
        setExplorerOpen((v) => !v);
      } else if (k === "j" || e.key === "`") {
        e.preventDefault();
        setTermOpen((v) => !v);
      } else if (k === "p") {
        e.preventDefault();
        setExplorerOpen(true);
        setTimeout(() => filterRef.current?.focus(), 0);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // Keep the active tab in view when the agent opens a file for you.
  useEffect(() => {
    const el = tabStripRef.current?.querySelector(".jvb-tab.active");
    el?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }, [activePath, openTabs.length]);

  const activeTab = openTabs.find((t) => t.path === activePath) || null;

  const visibleTree = useMemo(() => filterTree(tree, query.trim()), [
    tree,
    query,
  ]);
  const filterExpanded = useMemo(
    () => (query.trim() ? new Set(collectDirPaths(visibleTree)) : expanded),
    [query, visibleTree, expanded]
  );
  const fileCount = useMemo(() => countFiles(tree), [tree]);
  const matchCount = useMemo(() => countFiles(visibleTree), [visibleTree]);

  const codeLines = useMemo(() => {
    if (!activeTab || activeTab.welcome || activeTab.loading) return [];
    return String(activeTab.content ?? "").split("\n");
  }, [activeTab]);

  const copyActive = useCallback(async () => {
    if (!activeTab || activeTab.welcome) return;
    try {
      await navigator.clipboard.writeText(activeTab.content || "");
      setCopied(true);
      setTimeout(() => setCopied(false), 1400);
    } catch {
      setCopied(false);
    }
  }, [activeTab]);

  const useStarter = useCallback(
    (text) => {
      setInput(text);
      setPane("agent");
      setChatOpen(true);
      setTimeout(() => inputRef.current?.focus(), 0);
    },
    [setInput]
  );

  // Terminal content: each finished turn's full trace, then the in-flight one.
  const termTurns = [];
  turns.forEach((turn, i) => {
    if (turn.role === "assistant" && ((turn.lines || []).length || turn.meta)) {
      termTurns.push({ id: `t${i}`, lines: turn.lines || [], meta: turn.meta });
    }
  });
  if (busy && (lines.length || meta)) {
    termTurns.push({ id: "live", lines, meta });
  }

  const toolCount = termTurns.reduce(
    (n, t) => n + t.lines.filter((l) => l.kind === "tool").length,
    0
  );

  const onKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      submit(input);
    } else if (e.key === "Escape" && busy) {
      stop();
    }
  };

  const gridCols = [
    explorerOpen ? `${explorerW}px` : null,
    "minmax(0, 1fr)",
    chatOpen ? `${chatW}px` : null,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className="jvb">
      {/* title bar */}
      <div className="jvb-titlebar">
        <div className="jvb-lights">
          <span
            className="jvb-light r"
            role="button"
            tabIndex={0}
            onClick={onExit}
            onKeyDown={(e) => e.key === "Enter" && onExit && onExit()}
            title="Back to Explore"
          />
          <span className="jvb-light y" />
          <span className="jvb-light g" />
        </div>
        <span className="jvb-title">
          {rootName} — Jarvis Build
          <span className="jvb-title-badge">write + execute</span>
        </span>
        <div className="jvb-titlebar-right">
          {provider && (
            <span className="jvb-provider" title="Active LLM provider">
              <span className="jvb-provider-dot" aria-hidden="true" />
              {provider}
            </span>
          )}
          <button type="button" className="jvb-exit" onClick={onExit}>
            ← Explore
          </button>
        </div>
      </div>

      <div className="jvb-mid">
        {/* activity bar — VS Code's icon rail */}
        <nav className="jvb-activitybar" aria-label="Workspace panels">
          <button
            type="button"
            className={`jvb-act ${explorerOpen ? "jvb-act-on" : ""}`}
            title="Explorer (⌘/Ctrl+B)"
            aria-pressed={explorerOpen}
            onClick={() => setExplorerOpen((v) => !v)}
          >
            ▤
          </button>
          <button
            type="button"
            className="jvb-act"
            title="Filter files (⌘/Ctrl+P)"
            onClick={() => {
              setExplorerOpen(true);
              setTimeout(() => filterRef.current?.focus(), 0);
            }}
          >
            ⌕
          </button>
          <button
            type="button"
            className={`jvb-act ${termOpen ? "jvb-act-on" : ""}`}
            title="Terminal (⌘/Ctrl+J)"
            aria-pressed={termOpen}
            onClick={() => setTermOpen((v) => !v)}
          >
            ▷
          </button>
          <button
            type="button"
            className={`jvb-act ${chatOpen ? "jvb-act-on" : ""}`}
            title="Agent panel"
            aria-pressed={chatOpen}
            onClick={() => setChatOpen((v) => !v)}
          >
            ✦
          </button>
          <span className="jvb-act-sp" />
          <button
            type="button"
            className="jvb-act jvb-act-brand"
            title="Jarvis — Build mode"
            onClick={() => inputRef.current?.focus()}
          >
            ⚡
          </button>
        </nav>

        <div className="jvb-work">
          {/* narrow-screen pane switcher */}
          <div className="jvb-panes" role="tablist" aria-label="Panels">
            {[
              ["files", "Files"],
              ["editor", "Editor"],
              ["agent", "Agent"],
            ].map(([id, label]) => (
              <button
                key={id}
                type="button"
                role="tab"
                aria-selected={pane === id}
                className={`jvb-pane-btn ${pane === id ? "on" : ""}`}
                onClick={() => setPane(id)}
              >
                {label}
              </button>
            ))}
          </div>

          <div
            className={`jvb-body jvb-pane-${pane}`}
            style={{ gridTemplateColumns: gridCols }}
          >
            {/* explorer */}
            {explorerOpen && (
              <div className="jvb-explorer">
                <div className="jvb-panel-head">
                  Explorer
                  <span className="jvb-head-count">
                    {query.trim()
                      ? `${matchCount}/${fileCount}`
                      : fileCount || ""}
                  </span>
                  <button
                    type="button"
                    className="jvb-head-btn"
                    title="Reload the file tree"
                    onClick={loadTree}
                  >
                    ↻
                  </button>
                </div>
                <div className="jvb-filter">
                  <span className="jvb-filter-ic" aria-hidden="true">
                    ⌕
                  </span>
                  <input
                    ref={filterRef}
                    className="jvb-filter-input"
                    value={query}
                    placeholder="Filter files"
                    aria-label="Filter files"
                    onChange={(e) => setQuery(e.target.value)}
                    onKeyDown={(e) => e.key === "Escape" && setQuery("")}
                  />
                  {query && (
                    <button
                      type="button"
                      className="jvb-filter-x"
                      title="Clear filter"
                      onClick={() => setQuery("")}
                    >
                      ✕
                    </button>
                  )}
                </div>
                <div className="jvb-tree">
                  {treeError ? (
                    <div className="jvb-tree-empty">
                      Build server not reachable. Start the local Jarvis with{" "}
                      <code>JARVIS_FULL_MODE=1</code>.
                    </div>
                  ) : treeLoading ? (
                    <div className="jvb-skel-wrap">
                      {[76, 58, 88, 64, 48, 70].map((w, i) => (
                        <div
                          className="jvb-skel"
                          style={{ width: `${w}%` }}
                          key={i}
                        />
                      ))}
                    </div>
                  ) : tree.length === 0 ? (
                    <div className="jvb-tree-empty">
                      Empty workspace. Ask Jarvis to create the first file.
                    </div>
                  ) : visibleTree.length === 0 ? (
                    <div className="jvb-tree-empty">
                      No file matches “{query}”.
                    </div>
                  ) : (
                    visibleTree.map((node) => (
                      <TreeNode
                        key={node.path}
                        node={node}
                        depth={0}
                        activePath={activePath}
                        recentPath={recentPath}
                        expanded={filterExpanded}
                        query={query.trim()}
                        onToggle={toggleFolder}
                        onOpen={openFile}
                      />
                    ))
                  )}
                </div>
                <div
                  className="jvb-vsplit jvb-vsplit-left"
                  onMouseDown={startExplorerResize}
                  title="Drag to resize"
                />
              </div>
            )}

            {/* editor */}
            <div className="jvb-editor">
              <div className="jvb-tabs" ref={tabStripRef} role="tablist">
                {openTabs.length === 0 ? (
                  <span className="jvb-tab jvb-tab-empty">no file open</span>
                ) : (
                  openTabs.map((t) => (
                    <button
                      key={t.path}
                      type="button"
                      role="tab"
                      aria-selected={activePath === t.path}
                      title={t.welcome ? "Welcome" : t.path}
                      className={`jvb-tab ${
                        activePath === t.path ? "active" : ""
                      } ${t.welcome ? "jvb-tab-welcome" : ""}`}
                      onClick={() => setActivePath(t.path)}
                      onAuxClick={(e) => e.button === 1 && closeTab(t.path, e)}
                    >
                      {!t.welcome && (
                        <span
                          className="jvb-tab-ic"
                          style={{ color: fileMeta(t.path)[1] }}
                          aria-hidden="true"
                        >
                          {fileMeta(t.path)[0]}
                        </span>
                      )}
                      <span className="jvb-tab-name">
                        {t.welcome ? "✦ Welcome" : baseName(t.path)}
                      </span>
                      <span
                        className="jvb-tab-x"
                        role="button"
                        tabIndex={-1}
                        aria-label={`Close ${
                          t.welcome ? "Welcome" : baseName(t.path)
                        }`}
                        onClick={(e) => closeTab(t.path, e)}
                      >
                        ✕
                      </span>
                    </button>
                  ))
                )}
              </div>

              {/* breadcrumb + editor actions */}
              {activeTab && !activeTab.welcome && (
                <div className="jvb-crumbs">
                  <span className="jvb-crumb-root">{rootName}</span>
                  {activeTab.path.split("/").map((seg, i, arr) => (
                    <React.Fragment key={`${seg}-${i}`}>
                      <span className="jvb-crumb-sep">›</span>
                      <span
                        className={`jvb-crumb ${
                          i === arr.length - 1 ? "leaf" : ""
                        }`}
                      >
                        {seg}
                      </span>
                    </React.Fragment>
                  ))}
                  <span className="jvb-crumb-sp" />
                  {!isMarkdown(activeTab.path) && (
                    <button
                      type="button"
                      className={`jvb-crumb-btn ${wrap ? "on" : ""}`}
                      onClick={() => setWrap((w) => !w)}
                      title="Toggle word wrap"
                    >
                      ⏎ wrap
                    </button>
                  )}
                  <button
                    type="button"
                    className="jvb-crumb-btn"
                    onClick={() => reloadFile(activeTab.path)}
                    title="Reload from disk"
                  >
                    ↻
                  </button>
                  <button
                    type="button"
                    className="jvb-crumb-btn"
                    onClick={copyActive}
                    title="Copy file contents"
                  >
                    {copied ? "copied" : "copy"}
                  </button>
                </div>
              )}

              <div className="jvb-editor-body">
                {!activeTab || activeTab.welcome ? (
                  <BuildWelcome onStarter={useStarter} />
                ) : activeTab.loading ? (
                  <div className="jvb-editor-empty">
                    <span className="jvb-spinner" aria-hidden="true" />
                    Reading {baseName(activeTab.path)}…
                  </div>
                ) : isMarkdown(activeTab.path) ? (
                  <div className="jvb-md">
                    <MdLite text={activeTab.content} />
                  </div>
                ) : (
                  <div className={`jvb-codewrap ${wrap ? "wrap" : ""}`}>
                    <div className="jvb-gutter" aria-hidden="true">
                      {codeLines.map((_, i) => (
                        <span key={i}>{i + 1}</span>
                      ))}
                    </div>
                    <pre className="jvb-code">
                      <code>{activeTab.content}</code>
                    </pre>
                  </div>
                )}
              </div>
            </div>

            {/* agent chat */}
            {chatOpen && (
              <div className="jvb-chat">
                <div
                  className="jvb-vsplit jvb-vsplit-right"
                  onMouseDown={startChatResize}
                  title="Drag to resize"
                />
                <div className="jvb-panel-head">
                  Agent
                  {busy && <span className="jvb-head-live">● thinking</span>}
                </div>
                <div
                  className="jvb-chat-scroll"
                  ref={chatRef}
                  onScroll={(e) => setChatPinned(isAtBottom(e.currentTarget))}
                >
                  {turns.length === 0 && !busy && (
                    <div className="jvb-chat-empty">
                      Ask for something concrete — a file to create, a bug to
                      find, a command to run. Jarvis works in {rootName}.
                    </div>
                  )}
                  {turns.map((turn, i) =>
                    turn.role === "user" ? (
                      <div className="jvb-msg jvb-msg-user" key={i}>
                        {turn.content}
                      </div>
                    ) : (
                      <div className="jvb-msg jvb-msg-asst" key={i}>
                        {/* Thinking persists after the answer — the whole point is to
                            show HOW it decided, not just what it concluded. */}
                        <Reasoning text={turn.thinking} defaultOpen={false} />
                        {turn.content ? (
                          <MdLite text={turn.content} />
                        ) : (
                          <span className="jvb-msg-dim">…</span>
                        )}
                      </div>
                    )
                  )}
                  {busy && (
                    <div className="jvb-msg jvb-msg-asst">
                      <Reasoning text={thinking} defaultOpen live />
                      {streaming ? (
                        <MdLite text={streaming} />
                      ) : (
                        <span className="jvb-msg-dim">
                          <span className="jvb-dots">
                            <i />
                            <i />
                            <i />
                          </span>
                          working…
                        </span>
                      )}
                    </div>
                  )}
                </div>
                {!chatPinned && (
                  <button
                    type="button"
                    className="jvb-jump"
                    onClick={() => {
                      setChatPinned(true);
                      if (chatRef.current)
                        chatRef.current.scrollTop =
                          chatRef.current.scrollHeight;
                    }}
                  >
                    ↓ latest
                  </button>
                )}
                {sessionState === "creating" && (
                  <div className="jvb-session jvb-session-wait">
                    <span className="jvb-session-spin" aria-hidden="true" />
                    Spinning up your sandbox… (first run takes ~10–30s)
                  </div>
                )}
                {sessionState === "error" && (
                  <div className="jvb-session jvb-session-err">
                    Couldn't start a sandbox.
                    <button
                      type="button"
                      className="jvb-session-retry"
                      onClick={onRetrySession}
                    >
                      Retry
                    </button>
                  </div>
                )}
                {sessionState === "blocked" && (
                  <div className="jvb-session jvb-session-wall">
                    <div className="jvb-wall-title">
                      {sessionMessage ||
                        "You've used your free live Build runs for today."}
                    </div>
                    <div className="jvb-wall-sub">
                      Build runs a real agent in a real sandbox, so live runs
                      are limited. It resets tomorrow — meanwhile, watch a
                      recorded Build session, or explore the read-only agent.
                    </div>
                    <div className="jvb-wall-cta">
                      {onWatchDemo && (
                        <button
                          type="button"
                          className="jvb-wall-btn jvb-wall-btn-primary"
                          onClick={onWatchDemo}
                        >
                          ▶ Watch a recorded Build session
                        </button>
                      )}
                      <button
                        type="button"
                        className="jvb-wall-btn"
                        onClick={onExit}
                      >
                        ← Explore (read-only, free)
                      </button>
                    </div>
                  </div>
                )}
                {sessionState === "ready" && quota && (
                  <div className="jvb-session jvb-session-runs">
                    {quota.remaining} of {quota.limit} free live runs left today
                  </div>
                )}
                <div className={`jvb-composer ${busy ? "busy" : ""}`}>
                  <textarea
                    ref={inputRef}
                    className="jvb-input"
                    placeholder={
                      sessionState === "creating"
                        ? "Preparing your sandbox…"
                        : sessionState === "error"
                        ? "Sandbox unavailable — retry above"
                        : sessionState === "blocked"
                        ? "Out of free live runs — back tomorrow"
                        : "Ask Jarvis to build, edit, or run something…"
                    }
                    value={input}
                    rows={2}
                    disabled={sessionState !== "ready"}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={onKeyDown}
                  />
                  {busy ? (
                    <button
                      type="button"
                      className="jvb-send jvb-stop"
                      onClick={stop}
                      title="Stop (Esc)"
                    >
                      ■
                    </button>
                  ) : (
                    <button
                      type="button"
                      className="jvb-send"
                      onClick={() => submit(input)}
                      disabled={!input.trim() || sessionState !== "ready"}
                      title="Send (Enter)"
                    >
                      ↑
                    </button>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* terminal — draggable height like VS Code's bottom panel */}
          <div
            className={`jvb-terminal ${termOpen ? "" : "collapsed"}`}
            style={{ height: `${termOpen ? termHeight : TERM_MIN}px` }}
          >
            <div
              className="jvb-term-resizer"
              onMouseDown={startTermResize}
              title="Drag to resize"
            />
            <div className="jvb-panel-head jvb-term-head">
              <span>Terminal</span>
              {busy && <span className="jvb-term-live">● running</span>}
              {toolCount > 0 && (
                <span className="jvb-head-count">
                  {toolCount} tool call{toolCount === 1 ? "" : "s"}
                </span>
              )}
              <span className="jvb-head-sp" />
              <button
                type="button"
                className="jvb-head-btn"
                title={
                  termOpen
                    ? "Collapse panel (⌘/Ctrl+J)"
                    : "Expand panel (⌘/Ctrl+J)"
                }
                onClick={() => setTermOpen((v) => !v)}
              >
                {termOpen ? "⌄" : "⌃"}
              </button>
            </div>
            {termOpen && (
              <div
                className="jvb-term-body"
                ref={termRef}
                onScroll={(e) => setTermPinned(isAtBottom(e.currentTarget))}
              >
                {termTurns.length === 0 ? (
                  <div className="jvb-term-empty">
                    $ reasoning, tool calls with timings, and command output
                    appear here as the agent works.
                  </div>
                ) : (
                  termTurns.map((t) => (
                    <TerminalTurn key={t.id} lines={t.lines} meta={t.meta} />
                  ))
                )}
              </div>
            )}
            {termOpen && !termPinned && termTurns.length > 0 && (
              <button
                type="button"
                className="jvb-jump jvb-jump-term"
                onClick={() => {
                  setTermPinned(true);
                  if (termRef.current)
                    termRef.current.scrollTop = termRef.current.scrollHeight;
                }}
              >
                ↓ latest
              </button>
            )}
          </div>
        </div>
      </div>

      {/* status bar */}
      <div className="jvb-statusbar">
        <span className="jvb-sb jvb-sb-mode">◆ BUILD · write + execute</span>
        <span className="jvb-sb">⎇ {rootName}</span>
        {activeTab && !activeTab.welcome && (
          <>
            <span className="jvb-sb jvb-sb-path" title={activeTab.path}>
              {activeTab.path}
            </span>
            <span className="jvb-sb">
              {codeLines.length} line{codeLines.length === 1 ? "" : "s"}
            </span>
          </>
        )}
        <span className="jvb-sb-sp" />
        <span className="jvb-sb">{provider || "—"}</span>
        <span className={`jvb-sb ${busy ? "jvb-sb-run" : "jvb-sb-ok"}`}>
          ● {busy ? "running" : "ready"}
        </span>
      </div>
    </div>
  );
};

export default JarvisBuild;
