// BuildDemo.js — a recorded Build session, replayed.
//
// Public Build gives a visitor a few free live sandbox sessions a day. When
// those run out (or before they spend one), this shows what Build actually does:
// a real task, the agent's plan, the files it writes, the commands it runs, and
// the result — played back frame by frame on the same color-coded trajectory
// lanes the live terminal uses. It is labelled "recorded" throughout; the point
// is to show the shape of a Build turn, not to pass a replay off as live.

import React, { useCallback, useEffect, useRef, useState } from "react";
import "./BuildDemo.css";

// A real, representative task. Each frame appears at its `at` offset (ms). Tool
// frames carry the call, its timing, and the one-line result the trace shows;
// `file` marks a write so the "files created" strip fills as it plays.
const DEMO = {
  task:
    'Build a landing page for a coffee shop with a working "orders" counter.',
  model: "nvidia/nemotron-3-super-120b",
  plan:
    "The workspace is empty, so I'll scaffold from scratch: index.html for the " +
    "markup, styles.css for the look, and app.js for the counter button. Then " +
    "I'll list the tree and syntax-check the JS so I know it actually runs.",
  frames: [
    { at: 400, kind: "think" },
    {
      at: 1300,
      kind: "tool",
      call: 'get_file_tree(path=".")',
      ms: 96,
      summary: "1 entry · README.md",
    },
    {
      at: 2300,
      kind: "tool",
      call: 'write_file(path="index.html", content="<!DOCTYPE html>…")',
      ms: 182,
      summary: "wrote index.html · 42 lines",
      file: "index.html",
    },
    {
      at: 3200,
      kind: "tool",
      call: 'write_file(path="styles.css", content="body{font-family:…")',
      ms: 121,
      summary: "wrote styles.css · 28 lines",
      file: "styles.css",
    },
    {
      at: 4100,
      kind: "tool",
      call: 'write_file(path="app.js", content="let orders=0;const…")',
      ms: 88,
      summary: "wrote app.js · 14 lines",
      file: "app.js",
    },
    {
      at: 5100,
      kind: "tool",
      call: 'run_command(command="ls -1")',
      ms: 143,
      summary: "app.js\nindex.html\nstyles.css",
    },
    {
      at: 6200,
      kind: "tool",
      call: 'run_command(command="node --check app.js")',
      ms: 214,
      summary: "syntax OK — no errors",
    },
    {
      at: 7000,
      kind: "answer",
      text:
        "Done. I scaffolded a three-file coffee-shop landing page — `index.html`, " +
        "`styles.css`, and `app.js` — with an **Order** button that increments a " +
        "live counter, and syntax-checked the script so it runs cleanly.",
    },
    { at: 7400, kind: "done", meta: "6 tools · 6.4s · 9,240 in / 512 out" },
  ],
};

// Collapse an over-long quoted arg so a write_file(content="…800 chars") call
// doesn't blow out the line — the same tidy the live terminal does.
function tidyCall(call) {
  return (call || "").replace(/(["'])((?:\\.|(?!\1)[^\\])*)\1/g, (m, q, body) =>
    body.length > 40 ? `${q}${body.slice(0, 40)}…${q}` : m
  );
}

const fmtMs = (ms) =>
  ms < 1000 ? `${Math.round(ms)}ms` : `${(ms / 1000).toFixed(1)}s`;

function BuildDemo({ onClose, sessionsPerDay = 3 }) {
  const [shown, setShown] = useState(0); // how many frames have played
  const [run, setRun] = useState(0); // replay counter
  const [playing, setPlaying] = useState(true);
  const timers = useRef([]);

  const clearTimers = () => {
    timers.current.forEach(clearTimeout);
    timers.current = [];
  };

  const start = useCallback(() => {
    clearTimers();
    setShown(0);
    setPlaying(true);
    const reduce =
      typeof window !== "undefined" &&
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    if (reduce) {
      setShown(DEMO.frames.length);
      setPlaying(false);
      return;
    }
    DEMO.frames.forEach((f, i) => {
      timers.current.push(
        setTimeout(() => {
          setShown(i + 1);
          if (i === DEMO.frames.length - 1) setPlaying(false);
        }, f.at)
      );
    });
  }, []);

  useEffect(() => {
    start();
    return clearTimers;
  }, [start, run]);

  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const visible = DEMO.frames.slice(0, shown);
  const planShown = visible.some((f) => f.kind === "think");
  const files = visible.filter((f) => f.file).map((f) => f.file);
  const tools = visible.filter((f) => f.kind === "tool");
  const answer = visible.find((f) => f.kind === "answer");
  const done = visible.find((f) => f.kind === "done");

  return (
    <div
      className="jvd-modal"
      role="dialog"
      aria-modal="true"
      aria-label="Recorded Build session"
    >
      <div className="jvd-backdrop" onClick={onClose} />
      <div className="jvd-panel">
        <div className="jvd-bar">
          <span className="jvd-badge">▶ recorded Build session</span>
          <span className="jvd-bar-note">a real run, replayed — not live</span>
          <button
            type="button"
            className="jvd-x"
            onClick={onClose}
            aria-label="Close"
          >
            ✕
          </button>
        </div>

        <div className="jvd-task">
          <span className="jvd-task-label">Task</span>
          {DEMO.task}
        </div>

        <div className="jvd-body">
          {planShown && (
            <div className="jvd-plan">
              <span className="jv-lane jv-lane-think">plan</span>
              <span className="jvd-plan-text">{DEMO.plan}</span>
            </div>
          )}

          {files.length > 0 && (
            <div className="jvd-files">
              <span className="jvd-files-label">files created</span>
              {files.map((f) => (
                <span className="jvd-file" key={f}>
                  {f}
                </span>
              ))}
            </div>
          )}

          {tools.map((f, i) => (
            <div className="jvd-step" key={i}>
              <div className="jvd-step-call">
                <span className="jv-lane jv-lane-tool">tool</span>
                <code className="jvd-code">{tidyCall(f.call)}</code>
                <span className="jvd-ms">{fmtMs(f.ms)}</span>
                <span className="jvd-ok">✓</span>
              </div>
              {f.summary && (
                <div className="jvd-step-result">
                  <span className="jv-lane jv-lane-result">result</span>
                  <span className="jvd-summary">{f.summary}</span>
                </div>
              )}
            </div>
          ))}

          {playing && (
            <div className="jvd-working">
              working
              <span className="jvd-dots" aria-hidden="true" />
            </div>
          )}

          {answer && <div className="jvd-answer">{answer.text}</div>}

          {done && (
            <div className="jvd-done">
              <span className="jv-lane jv-lane-done">done</span>
              {done.meta}
            </div>
          )}
        </div>

        <div className="jvd-foot">
          <span className="jvd-foot-note">
            This is a replay. Live Build gives you {sessionsPerDay} free sandbox
            sessions a day — resets tomorrow.
          </span>
          <div className="jvd-foot-actions">
            {!playing && (
              <button
                type="button"
                className="jvd-replay"
                onClick={() => setRun((n) => n + 1)}
              >
                ↻ replay
              </button>
            )}
            <button type="button" className="jvd-close-btn" onClick={onClose}>
              Close
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default BuildDemo;
